# %% [markdown]
# # CASMI 2026 — specs_scratch R5: analogue channel audit (Colab)
#
# **Generated by `scratch_pkg/tools/mk_notebook.py r5_audit_colab` from `scratch_pkg/drivers/r5_audit_colab.py` —
# do not hand-edit.** Gate R5.audit pre-registered in `specs/specs_scratch/gate_report.md` (R5 section); design in
# `specs/specs_scratch/pssm.md`. Informational: it runs alongside the LB probes and explains, the LB decides.
#
# Runtime: **GPU T4** (FPNet logits), High-RAM. Stage results are cached in `casmi_2026/_r5_audit/`; a re-run skips
# finished stages. The open ±200 Da analogue search is the slow part (~10 s / molecule on CPU).
#
# Needs under `MyDrive/casmi_2026/`:
# - `enveda-CASMI26-molecule-id-mass-spectra/train.parquet`
# - `casmi26-scratch-pool/` v2 (R1 pool + `pool_npc.parquet`; the R1b subset is used, as in the probes)
# - `casmi26-fpnet-full1/` (fpnet_full1.pt) + `casmi26-v2-pool/` (fp_bits.npy, pool_fp.npy, pool_meta.parquet)
#
# Slice I (enveda-np-examples, one molecule per ik14): own structure banned from the library, sv = 0, the truth
# counted as non-train. Arms: FP list off/on × analogue list none/pssm/tani × class vote off/on. The R3 base is
# `fp1_none_v1`. Also writes `analog_q.npy` (the PSSM background over the non-train R1b pool) for optional upload.
#
# Paste the final printout back into the chat.

# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
POOL_DIR = ROOT / "casmi26-scratch-pool"
OUT = ROOT / "_r5_audit"
WORKERS = os.cpu_count() or 2
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
OUT.mkdir(parents=True, exist_ok=True)

RDKIT_PIN = "2026.03.3"
r_ = subprocess.run([sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}"], capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("rdkit install failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__

import numpy as np  # noqa: E402
import torch  # noqa: E402

from casmi_scratch import audit, fpnet  # noqa: E402
from casmi_scratch.analog import AnalogBank, estimate_q, train_smiles  # noqa: E402
from casmi_scratch.config import Config  # noqa: E402
from casmi_scratch.library import load_library, remap_keys  # noqa: E402
from casmi_scratch.pool import F_TRAIN, load_keymap, load_pool, npc_top1  # noqa: E402

CFG = Config().with_(frag_workers=WORKERS, pool_source="r1", pool_drop_e180=True, fp_channel="ahmed")
T0 = time.time()
print(f"torch {torch.__version__} cuda {torch.cuda.is_available()}")


def find(name):
    for depth in ("*", "*/*", "*/*/*"):
        hits = sorted(ROOT.glob(f"{depth}/{name}"), key=lambda p: len(str(p)))
        if hits:
            return hits[0]
    raise FileNotFoundError(f"{name} not found under {ROOT}")


def stage(name, fn):
    path = OUT / f"{name}.json"
    if path.exists():
        print(f"[{name}] cached")
        return json.loads(path.read_text())
    t = time.time()
    res = fn()
    path.write_text(json.dumps(res, indent=1, default=str))
    print(f"[{name}] {time.time() - t:.0f}s")
    return res


TRAIN = str(find("train.parquet"))
KEYMAP = load_keymap(str(POOL_DIR))
TRUTH = lambda ik: KEYMAP.get(ik, ik)  # noqa: E731
LIB = remap_keys(load_library(TRAIN, struct_mass=CFG.struct_mass), KEYMAP)
POOL, INFO = load_pool(str(POOL_DIR), drop_e180=True, with_npc=True)
VOTE_LABEL = npc_top1(str(POOL_DIR), set(LIB.ik))
SLICE = audit.load_slice(TRAIN)
print(f"slice I {len(SLICE)} | pool r1b {len(POOL):,} | library {len(LIB):,} | vote labels {len(VOTE_LABEL):,}")

# %% [markdown]
# ## FPNet full1 bank, analogue bank, background q

# %%
paths, bits, ref = fpnet.find_bank_files("ahmed", str(ROOT / "casmi26-fpnet-full1"),
                                         bits_dirs=[str(ROOT / "casmi26-v2-pool")])
FP = fpnet.load_bank("ahmed", paths, bits)
r = fpnet.parity_reference("ahmed", ref)
print(FP.describe(), "parity", None if r is None else f"{fpnet.featuriser_parity(FP.feat, *r)}/{len(r[0])}")

AN = AnalogBank(train_smiles(TRAIN, KEYMAP), None, CFG)
QF = OUT / "analog_q.npy"
if not QF.exists():
    t = time.time()
    np.save(QF, estimate_q(POOL, AN.feat, CFG.analog_q_n, mask=(np.asarray(POOL.flags, np.int64) & F_TRAIN) == 0))
    print(f"[q] {time.time() - t:.0f}s")
AN.q = np.load(QF)
print(f"[analog] {len(AN.smiles_of):,} library structures with SMILES | q mean {AN.q.mean():.4f}, "
      f"q > 0 on {(AN.q > 0).sum():,} of {len(AN.q):,} bits")

# %% [markdown]
# ## R5.audit on slice I

# %%
rows = stage("slice_i", lambda: audit.analog_discrimination(SLICE, LIB, POOL, TRUTH, FP, AN, CFG,
                                                            vote_label=VOTE_LABEL))
RES = audit.summarize_analog(rows, CFG.topn)
print(json.dumps(RES, indent=1))

# %% [markdown]
# ## Verdict (pre-registered)

# %%
b = RES["base"]
print(f"R5.audit slice I: n {RES['n']} (truth in range {RES['n_in_range']}); base {b} MRR@25 {RES['mrr'][b]:.4f}; "
      f"analogue search median {RES['an_s_median']:.1f}s / molecule, total {RES['an_s_total'] / 60:.0f} min")
for m in ("pssm", "tani"):
    arm = b.replace("none", m)
    print(f"  {m}: {arm} MRR@25 {RES['mrr'][arm]:.4f} (Δ {RES[m + '_delta']:+.4f}, bar +0.010); up {RES['up'][arm]} / "
          f"down {RES['down'][arm]}; coverage {RES[m + '_coverage']:.3f} (median {RES[m + '_n_median']:.0f} "
          f"analogues); analogue-only MRR {RES[m + '_only_mrr']}")
    print(f"  {'PASS' if RES[m + '_pass'] else 'FAIL'}  R5.audit ({m})")
for k in sorted(RES["mrr"]):
    print(f"    {k}: {RES['mrr'][k]:.4f}  up {RES['up'][k]} / down {RES['down'][k]}")
(OUT / "verdicts.json").write_text(json.dumps(dict(results=RES, total_s=round(time.time() - T0, 1)), indent=1,
                                              default=str))
